func hash(s string)Hash{if s==""{return Hash{}};h:=sha256.Sum256([]byte(s));return Hash{true,len(s),hex.EncodeToString(h[:])}}
func text(c *Call)[13]*string{return [13]*string{&c.Agent,&c.Session,&c.ThreadID,&c.Model,&c.Requested,&c.Effort,&c.Cwd,&c.Upstream,&c.AccountID,&c.UserID,&c.Error,&c.ErrorText,&c.File}}
func readShard(p string)(s State,calls []Call,nframes int,err error){b,e:=os.ReadFile(p);if e!=nil{return s,nil,0,e};at:=0;more:=false;for at<len(b){if len(b)-at<8{return s,nil,nframes,fmt.Errorf("truncated header")};size:=int(binary.LittleEndian.Uint32(b[at:]));crc:=binary.LittleEndian.Uint32(b[at+4:]);at+=8;if size<1||size>len(b)-at{return s,nil,nframes,fmt.Errorf("frame length")};data:=b[at:at+size];at+=size;if crc32.ChecksumIEEE(data)!=crc{return s,nil,nframes,fmt.Errorf("crc mismatch")};var f Frame;if e=gob.NewDecoder(bytes.NewReader(data)).Decode(&f);e!=nil{return s,nil,nframes,e};nframes++;if nframes>1&&s.Path!=f.State.Path{return s,nil,nframes,fmt.Errorf("path mismatch")};s=f.State;more=f.More;for _,x:=range f.Patches{c:=x.Call;for j,z:=range text(&c){if int(x.Text[j])>=len(f.Strings){return s,nil,nframes,fmt.Errorf("string index")};*z=f.Strings[x.Text[j]]};c.File=s.Path;if x.Index<0||x.Index>len(calls){return s,nil,nframes,fmt.Errorf("patch index")};if x.Index==len(calls){calls=append(calls,c)}else{calls[x.Index]=c}}};if more{return s,nil,nframes,fmt.Errorf("incomplete write")};return}
